cd /workspace/nox/web/site
python3 - <<'P'
import re,time
t=str(int(time.time()))
tags='<link rel="stylesheet" href="/web/nox-ai-s1.css?v=%s"><link rel="stylesheet" href="/web/nox-sl-s1.css?v=%s"><script src="/web/nox-ai-s1.js?v=%s" defer></script><script src="/web/nox-sl-s1.js?v=%s" defer></script>'%(t,t,t,t)
for p in ['atlas','finance','money','pdf','voice','index','chat','assistant']:
    fn=p+'.html'; s=open(fn,encoding='utf-8').read()
    s=re.sub(r'<link rel="stylesheet" href="/web/nox-(ai|sl)-s1\.css[^"]*">','',s); s=re.sub(r'<script src="/web/nox-(ai|sl)-s1\.js[^"]*" defer></script>','',s)
    s=s.replace('</body>',tags+'</body>',1); open(fn,'w',encoding='utf-8').write(s)
print('ai ok')
P
for f in atlas finance pdf voice; do cat >> qa/rework/$f.fixed <<'F'
ИИ (S1): кнопка «NOX, ...» открывает стеклянную панель sl-drawer; запрос идёт в /api/chat с контекстом страницы, ответ потоком; если данных нет (нет PDF, записей, текста), честное сообщение. Нативные контролы показаны как sl-* (nox-sl-s1.js).
F
done
